// Cadence per Jonathan's explicit compliance-cadence instruction (supersedes the earlier 05 §4
// numbers - 6/4/8 attempts by disposition type, 4 waves, 90-120 day gaps - with a tighter,
// week-scoped two-wave model; 05 §4's own text isn't edited, this is a deliberate live
// instruction overriding what that doc stated as of the prior pass):
//   Wave 1 ("new lead"): worked daily (bounded by the separate per-day cap enforced at claim time
//     in hopper-request-next.workflow.json / W3.1, not here) for up to 14 days back-to-back from
//     its first attempt, capped at 7 total attempts - whichever limit hits first ends the wave.
//   Wave 2 ("2nd rotation"): starts after a 14-day gap (lands around week 4 from the lead's first
//     attempt), worked for up to 3 days back-to-back from ITS OWN first attempt, capped at 4 total
//     attempts (Jonathan said 3 or 4 - used the higher bound, easy to tighten to 3).
//   Exhausting wave 2 (either limit) moves the entry to the future-rework queue (HopperEntry
//     status 'FutureRework', new this pass) - a distinct, revisitable holding state, not a
//     permanent stop like OptedOut. Reviving FutureRework entries into a new campaign/wave 1 isn't
//     built this pass - flagged, not silently assumed solved.
const WAVE_LIMITS = {
  1: { maxAttempts: 7, maxDays: 14 },
  2: { maxAttempts: 4, maxDays: 3 },
};
const WAVE_2_GAP_DAYS = 14;
const TRY_BACK_DISPOSITIONS = ['NoAnswer', 'Busy', 'GatekeeperOnly', 'VoicemailLeft'];
const MS_PER_DAY = 24 * 60 * 60 * 1000;

function isSameLocalDay(a, b) {
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();
}

const input = $input.first().json.body;
const {
  disposition,
  attemptCountThisWave,
  wave,
  lastAttemptDate,
  firstAttemptDateThisWave,
  attemptCountToday,
  repId,
  scheduledAt,
} = input;

const now = new Date();
const wasAttemptedToday = lastAttemptDate && isSameLocalDay(new Date(lastAttemptDate), now);
const newAttemptCountToday = wasAttemptedToday ? (attemptCountToday || 0) + 1 : 1;

if (disposition === 'OptOut') {
  return [{ json: { action: 'STOP', hopperStatus: 'OptedOut', claimedByRepId: null, nextOwner: 'none', attemptCountToday: newAttemptCountToday, reason: 'Opt-out is a hard stop, no further attempts ever.' } }];
}

// Callback is its own top-level disposition (NOT a Connected- prefixed value) - see
// CRM-OBJECT-MODEL.md's Callback vs. Try-back distinction. Personal/rep-locked; scheduledAt (the
// rep's own optional date/time selection, per Jonathan's explicit 'select time date optional')
// becomes nextEligibleAt when given, otherwise the entry is simply locked to the rep with no
// specific due time.
if (disposition === 'Callback') {
  return [{
    json: {
      action: 'CALLBACK_SCHEDULED',
      hopperStatus: 'CallbackLocked',
      claimedByRepId: repId,
      nextOwner: 'rep',
      nextEligibleAt: scheduledAt || null,
      attemptCountToday: newAttemptCountToday,
      reason: scheduledAt
        ? `Callback requested and scheduled for ${scheduledAt} - locked to the rep who took the call.`
        : 'Callback requested, no specific time given - locked to the rep who took the call until they follow up.',
    },
  }];
}

if (disposition && disposition.startsWith('Connected-')) {
  return [{ json: { action: 'STOP', hopperStatus: 'Completed', claimedByRepId: null, nextOwner: 'none', attemptCountToday: newAttemptCountToday, reason: 'Connected - this workflow only recycles no-contact dispositions.' } }];
}

if (!TRY_BACK_DISPOSITIONS.includes(disposition)) {
  return [{ json: { action: 'REVIEW', hopperStatus: null, claimedByRepId: repId, nextOwner: 'rep', attemptCountToday: newAttemptCountToday, reason: `Unrecognized disposition "${disposition}" - not in the try-back set, needs a human look rather than an automated guess. Left claimed by the calling rep rather than silently returned to the pool.` } }];
}

// Try-back (NoAnswer/Busy/GatekeeperOnly/VoicemailLeft) - general behavior, not a distinct
// disposition value: goes straight back into the SHARED pool, not held for this rep, unless this
// wave's attempt cap or day-window is exhausted. "tryback are placed back in campaign hopper, keep
// leads being worked."
const limits = WAVE_LIMITS[wave] || WAVE_LIMITS[1];
const waveStart = firstAttemptDateThisWave ? new Date(firstAttemptDateThisWave) : now;
const daysIntoWave = (now - waveStart) / MS_PER_DAY;
const newAttemptCountThisWave = (attemptCountThisWave || 0) + 1;
const dayWindowExpired = daysIntoWave >= limits.maxDays;
const attemptCapReached = newAttemptCountThisWave >= limits.maxAttempts;

if (!dayWindowExpired && !attemptCapReached) {
  return [{
    json: {
      action: 'RETRY_NOW',
      hopperStatus: 'Available',
      claimedByRepId: null,
      nextOwner: 'pool',
      attemptCountThisWave: newAttemptCountThisWave,
      firstAttemptDateThisWave: waveStart.toISOString(),
      attemptCountToday: newAttemptCountToday,
      reason: `Wave ${wave || 1}, attempt ${newAttemptCountThisWave} of ${limits.maxAttempts} (day ${Math.floor(daysIntoWave) + 1} of ${limits.maxDays}).`,
    },
  }];
}

if ((wave || 1) === 1) {
  const nextEligible = new Date(now.getTime() + WAVE_2_GAP_DAYS * MS_PER_DAY);
  return [{
    json: {
      action: 'RECYCLE_NEXT_WAVE',
      hopperStatus: 'Available',
      claimedByRepId: null,
      nextOwner: 'pool',
      nextWave: 2,
      attemptCountThisWave: 0,
      firstAttemptDateThisWave: null,
      nextEligibleAt: nextEligible.toISOString(),
      attemptCountToday: newAttemptCountToday,
      reason: `Wave 1 exhausted (${limits.maxAttempts}-attempt cap or ${limits.maxDays}-day window) - recycles into wave 2, eligible ${WAVE_2_GAP_DAYS} days out.`,
    },
  }];
}

return [{
  json: {
    action: 'STOP_TO_REWORK',
    hopperStatus: 'FutureRework',
    claimedByRepId: null,
    nextOwner: 'none',
    attemptCountToday: newAttemptCountToday,
    reason: `Wave 2 exhausted (${limits.maxAttempts}-attempt cap or ${limits.maxDays}-day window) - moved to the future-rework queue, not re-dialed by the normal hopper flow.`,
  },
}];
